pageStyle:
.row.section-header { display: none; }

#byor_single_search {
    border: 2px solid #ff6600;
    padding: 20px;
}
.byor-single-search-results-groups{
justify-content: center !important;
}

.kc-home a.ss-explore {
    color: #007bff !important;
}

.mdkp-body{
background:white !important;
min-height:100px;
}
.mdkp-body.front-page {
    padding-bottom: 0px;
    display: none;
}
.fp-intro-logo{
min-width:0;
height:70px;
}
.fp-intro-section {
    flex-direction: column;
    align-items: center;
    margin: 30px 0 0;
}
.fp-intro-divider {
display:none;
}
.fp-intro-blurb {
    min-width: calc(50% - 20.5px);
    text-align: center;
    display: flex;
    align-items: center;
    justify-content: center;
}
.fp-intro-blurb-text {
    color: #ff6600;
    text-transform: uppercase;
    font-size: 14px;
    font-weight: bold;
    letter-spacing: 1px;
}
.page-description-content{
    width: 100%;
    display: flex;
    flex-direction: column;
}


.mdkp-body.flex-body.front-page {
    overflow-x: visible;
	flex: none;
}
.mdkp-body.flex-body:has(.kc-wrap){
	padding-top: 0;
}
.fp-search-section {
    margin: 50px 0 20px;
}
.multi-section.wrapper-section-0:has(.col-md-12.wrapper-section-0:empty){
	display: none;
}
#byor_single_search {
    border: 2px solid #ff6600;
    padding: 20px;
}
.col-md-12:has(.kc-wrap) {
    padding: 0;
}
